args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==2L,!dir.exists(args[[2]]));dir.create(args[[2]],recursive=TRUE)
value<-readRDS(args[[1]]);ids<-rownames(value$G);variants<-colnames(value$G)
num<-function(x)matrix(sprintf("%.17g",as.vector(x)),nrow=nrow(as.matrix(x)))
write<-function(frame,name)write.table(frame,file.path(args[[2]],name),sep="\t",quote=FALSE,row.names=FALSE,col.names=TRUE,na="NA",fileEncoding="UTF-8")
for(trait in c("continuous","binary"))write(data.frame(sample_id=ids,value=sprintf("%.17g",value[[trait]]),check.names=FALSE),paste0(trait,".tsv"))
write(data.frame(sample_id=ids,covariate=sprintf("%.17g",value$covariate)),"covariates.tsv")
g<-as.data.frame(num(value$G),stringsAsFactors=FALSE);names(g)<-variants;write(data.frame(sample_id=ids,g,check.names=FALSE),"genotypes.tsv")
sets<-rbind(data.frame(set_id="all-declared",variant_id=variants),data.frame(set_id="single-informative",variant_id=variants[[4]]),data.frame(set_id="monomorphic",variant_id=variants[[1]]));write(sets,"sets.tsv")
cat("PASS artificial120-sample inputs exported with17-digit numeric precision;no bundled/participant genotypes used\n")
